/* initializes the game by calling GameObjectsInit, PlayerFamilyInit, EntityFamilyRegisterAll,
   WeaponFamilyRegister, EffectFamilyRegister, StructureFamilyRegister, ItemFamilyRegister,
   ComponentFamilyRegister, TriggerFamilyRegister, ActionFamilyRegister, SteeringFamilyRegister,
   NodeFamilyRegister, ScreenElementFamilyRegister and ScreenFamilyRegisterAll */
uint32_t GameSystemsInit(void)
{
	uint32_t edx = 0;

	GameObjectsInit();
	PlayerFamilyInit();
	EntityFamilyRegisterAll();
	WeaponFamilyRegister();
	edx = EffectFamilyRegister();
	StructureFamilyRegister(edx);
	ItemFamilyRegister();
	ComponentFamilyRegister();
	TriggerFamilyRegister();
	ActionFamilyRegister();
	SteeringFamilyRegister();
	NodeFamilyRegister();
	ScreenElementFamilyRegister();
	return ScreenFamilyRegisterAll();
}

/* shuts the game down by calling sub_00113110, sub_000188A0, sub_00028040, sub_000A13A0,
   BuildingTypeTableShutdown, sub_000D7720, TriggerFamilyShutdown, sub_00039A60, NodeFamilyShutdown,
   ScreenElementFamilyShutdown, sub_000204E0 and GameObjectsShutdown */
uint32_t GameSystemsShutdown(uint32_t edx)
{
	sub_00113110();
	sub_000188A0();
	sub_00028040();
	sub_000A13A0();
	edx = BuildingTypeTableShutdown(edx);
	sub_000D7720();
	sub_00113110();
	TriggerFamilyShutdown();
	sub_00039A60();
	TriggerFamilyShutdown();
	NodeFamilyShutdown();
	edx = ScreenElementFamilyShutdown(edx);
	sub_000204E0();
	return GameObjectsShutdown(edx);
}

