	ebx = eax;
	eax = MEM32(0x1EA6ECu);
	MEM32(0x1EA7FCu) = 0u;
	MEM32(0x1EA800u) = 0u;
	MEM32(0x1EA804u) = 0u;
	MEM32(0x1EA808u) = 0u;
	if (eax != 0u && MEM32(0x1EA6F4u) != 0u)
	{
		f0 = x87_round(x87_round((double)(int32_t)MEM32(0x1EA6ECu) / (double)(int32_t)MEM32(0x1EA6F4u)) * 1e+02);
		if (!(f0 < 1e+02))
			MEM32(0x1EA7FCu) = 0x42C80000u;
		else
			MEMF(0x1EA7FCu) = (float)f0;
	}
	if (MEM32(0x1EA6F0u) != 0u && MEM32(0x1EA6F8u) != 0u)
	{
		f0 = x87_round(x87_round((double)(int32_t)MEM32(0x1EA6F0u) / (double)(int32_t)MEM32(0x1EA6F8u)) * 1e+02);
		if (!(f0 < 1e+02))
			MEM32(0x1EA800u) = 0x42C80000u;
		else
			MEMF(0x1EA800u) = (float)f0;
	}
	if (MEM32(0x1EA6E4u) != 0u && MEM32(0x1EA6DCu) != 0u)
	{
		f0 = x87_round(x87_round((double)(int32_t)MEM32(0x1EA6DCu) / (double)(int32_t)MEM32(0x1EA6E4u)) * 1e+02);
		if (!(f0 < 1e+02))
			MEM32(0x1EA804u) = 0x42C80000u;
		else
			MEMF(0x1EA804u) = (float)f0;
	}
	if (MEM32(0x1EA6E8u) != 0u && MEM32(0x1EA6E0u) != 0u)
	{
		f0 = x87_round(x87_round((double)(int32_t)MEM32(0x1EA6E0u) / (double)(int32_t)MEM32(0x1EA6E8u)) * 1e+02);
		if (!(f0 < 1e+02))
			MEM32(0x1EA808u) = 0x42C80000u;
		else
			MEMF(0x1EA808u) = (float)f0;
	}
