/* Sets the 0x100 bit of the flag word at offset 4 and, only when it was clear, enables the four indexed
   parts (0, 2, 1, 3) of the object at offset 0x194 through EntityPartSetEnabled with value 1. */
uint32_t EntityPartsEnable(uint32_t esi)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, eax = 0, ignored = 0;

	eax = MEM32(esi + 4u);
	if (((eax >> 8) & 1u) == 0u)
	{
		arg2 = 1u;
		MEM32(esi + 4u) = eax | 0x100u;
		arg1 = 0u;
		arg0 = MEM32(esi + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &ignored, &esi);
		arg2 = 1u;
		arg1 = 2u;
		arg0 = MEM32(esi + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &ignored, &esi);
		arg2 = 1u;
		arg1 = 1u;
		arg0 = MEM32(esi + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &ignored, &esi);
		arg2 = 1u;
		arg1 = 3u;
		arg0 = MEM32(esi + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &eax, &esi);
	}
	return eax;
}

