/* On A/Start or down/left-y pad input from any pad, calls GameObjectSetActive on edi and on the object
   at esi+0x20. */
void ScreenHandlePadInput(uint32_t esi, uint32_t edi)
{
	uint32_t arg0 = 0, arg1 = 0, eax = 0, ecx = 0;

	DoNothing();
	eax = MEM32(esi + 0x18u);
	if ((int32_t)eax < 0)
	{
		if (vcPad_pressed_a(vcPads(0)) != 0u || vcPad_pressed_start(vcPads(0)) != 0u || vcPad_pressed_a(vcPads(1)) != 0u || vcPad_pressed_start(vcPads(1)) != 0u || vcPad_pressed_a(vcPads(2)) != 0u || vcPad_pressed_start(vcPads(2)) != 0u || vcPad_pressed_a(vcPads(3)) != 0u || vcPad_pressed_start(vcPads(3)) != 0u)
		{
			arg1 = 0u;
			arg0 = edi;
			GameObjectSetActive(arg0, arg1);
			arg1 = 1u;
			arg0 = MEM32(esi + 0x20u);
			GameObjectSetActive(arg0, arg1);
			return;
		}
	}
	else
	{
		ecx = eax * 0x210u;
		if (MEM32(ecx + vcPad_pressed_a_VA(vcPads_VA)) != 0u || MEM32(ecx + vcPad_pressed_start_VA(vcPads_VA)) != 0u)
		{
			arg1 = 0u;
			arg0 = edi;
			GameObjectSetActive(arg0, arg1);
			arg1 = 1u;
			arg0 = MEM32(esi + 0x20u);
			GameObjectSetActive(arg0, arg1);
			return;
		}
	}
	if ((int32_t)eax < 0)
	{
		if (vcPad_pressed_down(vcPads(0)) != 0u || (vcPad_pressed_left_y(vcPads(0)) != 0u && (double)vcPad_left_y(vcPads(0)) < 0.0f) || vcPad_pressed_down(vcPads(1)) != 0u || (vcPad_pressed_left_y(vcPads(1)) != 0u && (double)vcPad_left_y(vcPads(1)) < 0.0f) || vcPad_pressed_down(vcPads(2)) != 0u || (vcPad_pressed_left_y(vcPads(2)) != 0u && (double)vcPad_left_y(vcPads(2)) < 0.0f) || vcPad_pressed_down(vcPads(3)) != 0u || (vcPad_pressed_left_y(vcPads(3)) != 0u && (double)vcPad_left_y(vcPads(3)) < 0.0f))
		{
			arg1 = 0u;
			arg0 = edi;
			GameObjectSetActive(arg0, arg1);
			arg1 = 1u;
			arg0 = MEM32(esi + 0x20u);
			GameObjectSetActive(arg0, arg1);
			return;
		}
		return;
	}
	eax = eax * 0x210u;
	if (MEM32(eax + vcPad_pressed_down_VA(vcPads_VA)) != 0u)
	{
		arg1 = 0u;
		arg0 = edi;
		GameObjectSetActive(arg0, arg1);
		arg1 = 1u;
		arg0 = MEM32(esi + 0x20u);
		GameObjectSetActive(arg0, arg1);
		return;
	}
	if (MEM32(eax + vcPad_pressed_left_y_VA(vcPads_VA)) == 0u)
		return;
	if (!(FLOAT_AT(eax + vcPad_left_y_VA(vcPads_VA)) < 0.0f))
		return;
	arg1 = 0u;
	arg0 = edi;
	GameObjectSetActive(arg0, arg1);
	arg1 = 1u;
	arg0 = MEM32(esi + 0x20u);
	GameObjectSetActive(arg0, arg1);
}

/* The ObjectivesScreen type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t ObjectivesScreen_StateMachine(uint32_t ebx, uint32_t ebp, uint32_t esi, uint32_t arg0, uint32_t arg1, uint32_t arg2, uint32_t arg3, uint32_t arg4)
{
	uint32_t arg0_2 = 0, arg1_2 = 0, eax = 0, ebx_2 = 0, ecx = 0, edi = 0, edx = 0, esi_2 = 0, ignored = 0;

	ecx = arg0;
	eax = arg3;
	edx = MEM32(eax + 4u);
	edi = MEM32(ecx);
	if (arg2 != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C8u)
		{
			arg0_2 = edi;
			GameObjectSendMessageToVisibleChildren(ebx, esi, arg0_2, &ignored, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C9u)
		{
			arg0_2 = edi;
			GameObjectBroadcastToVisibleChildren(arg0_2, &ignored, &ebx, &esi, &edi);
			eax = 1u;
			return eax;
		}
		if (eax != 0x32CAu)
		{
			if (eax == 0x32CBu)
			{
				esi_2 = arg1;
				ScreenHandlePadInput(esi_2, edi);
				eax = 1u;
				return eax;
			}
			if (eax != 0xFFFAu)
			{
				eax = 0u;
				return eax;
			}
			arg0_2 = edi;
			GameObjectClearPadAndDestroyChildren(arg0_2, &ignored, &edx);
			eax = 1u;
			return eax;
		}
		eax = arg1;
		arg1_2 = edi;
		arg0_2 = ecx;
		ScreenDrawListEntries(eax, ebx, ebp, esi, edi, arg0_2, arg1_2);
		eax = 1u;
		return eax;
	}
	ebx_2 = arg1;
	eax = arg4;
	arg1_2 = edi;
	arg0_2 = ecx;
	ScreenElementInitAndCreate(eax, edx, ebx_2, ebp, esi, edi, arg0_2, arg1_2);
	eax = 1u;
	return eax;
}

