		edx = MEM32(esi + 0xD0u);
		ecx = g_esp + 0xCu;
		g_esp = g_esp - 4u;
		MEM32(g_esp) = ecx;
		g_esp = g_esp - 4u;
		MEM32(g_esp) = edx;
		arg0 = MEM32(g_esp);
		arg1 = MEM32(g_esp + 4u);
		QuadtreeObjectInsert(esi, edi, arg0, arg1);
		g_esp = g_esp + 0x14u;
		g_esp = g_esp + 0xCu;
