		MEMF(eax + 8u) = (float)x87_round(x87_round(x87_round(FLOAT_AT(ecx + 4u) * FLOAT_AT(ecx + 0x14u)) - x87_round(FLOAT_AT(ecx + 8u) * FLOAT_AT(ecx + 0x10u))) * f0);
