	uint32_t arg0_2 = 0, arg1 = 0, arg2 = 0, arg3 = 0, eax = 0, edi_2 = 0, esi_2 = 0;
	double f0 = 0, f1 = 0, f2 = 0;

	g_esp = g_esp - 8u;
	MEM32(g_esp + 4u) = arg0;
	f0 = 0.0f;
	g_esp = g_esp - 0x24u;
	f1 = 1.0;
	g_esp = g_esp - 4u;
