		MEM32(g_esp) = esi_2;
		g_esp = g_esp - 4u;
		MEM32(g_esp) = 0u;
		eax = g_esp + 0x10u;
		g_esp = g_esp - 4u;
		MEM32(g_esp) = eax;
		g_esp = g_esp - 4u;
		MEM32(g_esp) = edi_2;
		arg0_2 = MEM32(g_esp);
		arg1 = MEM32(g_esp + 4u);
		arg2 = MEM32(g_esp + 8u);
		arg3 = MEM32(g_esp + 0xCu);
