/* Returns 1 when the sphere at arg0 (center at offsets 0/4/8, radius at 0xC) is within its radius of the
   axis-aligned box at arg1 (min at 0/4/8, max at 0xC/0x10/0x14), and 0 when the box is empty or the
   sphere is farther than the radius. */
uint32_t SphereIntersectsBox(uint32_t arg0, uint32_t arg1)
{
	uint32_t eax = 0, ecx = 0, edx = 0;
	double f0 = 0, f1 = 0, t1 = 0, t2 = 0;

	ecx = arg1;
	f0 = 0.0f;
	if (FLOAT_AT(ecx) > FLOAT_AT(ecx + 0xCu) && FLOAT_AT(ecx + 4u) > FLOAT_AT(ecx + 0x10u) && FLOAT_AT(ecx + 8u) > FLOAT_AT(ecx + 0x14u))
	{
		eax = 0u;
		return eax;
	}
	edx = arg0;
	if (!(FLOAT_AT(edx) < FLOAT_AT(ecx)))
	{
		if (FLOAT_AT(edx) > FLOAT_AT(ecx + 0xCu))
		{
			f0 = x87_round(FLOAT_AT(edx) - FLOAT_AT(ecx + 0xCu));
			f0 = x87_round(f0 * f0);
		}
	}
	else
	{
		f0 = x87_round(FLOAT_AT(edx) - FLOAT_AT(ecx));
		f0 = x87_round(f0 * f0);
	}
	t1 = FLOAT_AT(edx + 4u);
	f1 = FLOAT_AT(edx + 4u);
	if (t1 < FLOAT_AT(ecx + 4u))
	{
		f1 = x87_round(f1 - FLOAT_AT(ecx + 4u));
		f0 = x87_round(f0 + x87_round(f1 * f1));
		t2 = FLOAT_AT(edx + 8u);
		f1 = FLOAT_AT(edx + 8u);
		if (!(t2 < FLOAT_AT(ecx + 8u)))
		{
			if (!(f1 > FLOAT_AT(ecx + 0x14u)))
			{
				f1 = FLOAT_AT(edx + 0xCu);
				if (f0 > x87_round(f1 * f1))
				{
					eax = 0u;
					return eax;
				}
				eax = 1u;
				return eax;
			}
			f1 = x87_round(FLOAT_AT(edx + 8u) - FLOAT_AT(ecx + 0x14u));
		}
		else
			f1 = x87_round(f1 - FLOAT_AT(ecx + 8u));
		f0 = x87_round(f0 + x87_round(f1 * f1));
		f1 = FLOAT_AT(edx + 0xCu);
		if (f0 > x87_round(f1 * f1))
		{
			eax = 0u;
			return eax;
		}
		eax = 1u;
		return eax;
	}
	if (f1 > FLOAT_AT(ecx + 0x10u))
	{
		f1 = x87_round(FLOAT_AT(edx + 4u) - FLOAT_AT(ecx + 0x10u));
		f0 = x87_round(f0 + x87_round(f1 * f1));
	}
	t2 = FLOAT_AT(edx + 8u);
	f1 = FLOAT_AT(edx + 8u);
	if (!(t2 < FLOAT_AT(ecx + 8u)))
	{
		if (!(f1 > FLOAT_AT(ecx + 0x14u)))
		{
			f1 = FLOAT_AT(edx + 0xCu);
			if (f0 > x87_round(f1 * f1))
			{
				eax = 0u;
				return eax;
			}
			eax = 1u;
			return eax;
		}
		f1 = x87_round(FLOAT_AT(edx + 8u) - FLOAT_AT(ecx + 0x14u));
	}
	else
		f1 = x87_round(f1 - FLOAT_AT(ecx + 8u));
	f0 = x87_round(f0 + x87_round(f1 * f1));
	f1 = FLOAT_AT(edx + 0xCu);
	if (f0 > x87_round(f1 * f1))
	{
		eax = 0u;
		return eax;
	}
	eax = 1u;
	return eax;
}

/* Grows the bounds at arg0 (min at 0/4/8, max at 0xC/0x10/0x14) to include each of the arg1 vertices
   starting at arg2 and spaced by the arg3 stride. */
void BoxAddVertices(uint32_t arg0, uint32_t arg1, uint32_t arg2, uint32_t arg3)
{
	uint32_t ebp = 0, ebx = 0, ecx = 0, edi = 0, edx = 0, esi = 0;
	uint32_t t1 = 0;
	double f0 = 0;

	edx = arg0;
	ecx = arg2;
	ebp = arg3;
	esi = arg1;
	ebx = 0u;
	if ((int32_t)esi >= 4)
	{
		edi = 3u;
		do
		{
			if (FLOAT_AT(ecx) < FLOAT_AT(edx))
				MEM32(edx) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) < FLOAT_AT(edx + 4u))
				MEM32(edx + 4u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) < FLOAT_AT(edx + 8u))
				MEM32(edx + 8u) = MEM32(ecx + 8u);
			if (FLOAT_AT(ecx) > FLOAT_AT(edx + 0xCu))
				MEM32(edx + 0xCu) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) > FLOAT_AT(edx + 0x10u))
				MEM32(edx + 0x10u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) > FLOAT_AT(edx + 0x14u))
				MEM32(edx + 0x14u) = MEM32(ecx + 8u);
			f0 = FLOAT_AT(ecx + ebp);
			ecx += ebp;
			if (f0 < FLOAT_AT(edx))
				MEM32(edx) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) < FLOAT_AT(edx + 4u))
				MEM32(edx + 4u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) < FLOAT_AT(edx + 8u))
				MEM32(edx + 8u) = MEM32(ecx + 8u);
			if (FLOAT_AT(ecx) > FLOAT_AT(edx + 0xCu))
				MEM32(edx + 0xCu) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) > FLOAT_AT(edx + 0x10u))
				MEM32(edx + 0x10u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) > FLOAT_AT(edx + 0x14u))
				MEM32(edx + 0x14u) = MEM32(ecx + 8u);
			f0 = FLOAT_AT(ecx + ebp);
			ecx += ebp;
			if (f0 < FLOAT_AT(edx))
				MEM32(edx) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) < FLOAT_AT(edx + 4u))
				MEM32(edx + 4u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) < FLOAT_AT(edx + 8u))
				MEM32(edx + 8u) = MEM32(ecx + 8u);
			if (FLOAT_AT(ecx) > FLOAT_AT(edx + 0xCu))
				MEM32(edx + 0xCu) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) > FLOAT_AT(edx + 0x10u))
				MEM32(edx + 0x10u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) > FLOAT_AT(edx + 0x14u))
				MEM32(edx + 0x14u) = MEM32(ecx + 8u);
			f0 = FLOAT_AT(ecx + ebp);
			ecx += ebp;
			if (f0 < FLOAT_AT(edx))
				MEM32(edx) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) < FLOAT_AT(edx + 4u))
				MEM32(edx + 4u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) < FLOAT_AT(edx + 8u))
				MEM32(edx + 8u) = MEM32(ecx + 8u);
			if (FLOAT_AT(ecx) > FLOAT_AT(edx + 0xCu))
				MEM32(edx + 0xCu) = MEM32(ecx);
			if (FLOAT_AT(ecx + 4u) > FLOAT_AT(edx + 0x10u))
				MEM32(edx + 0x10u) = MEM32(ecx + 4u);
			if (FLOAT_AT(ecx + 8u) > FLOAT_AT(edx + 0x14u))
				MEM32(edx + 0x14u) = MEM32(ecx + 8u);
			edi += 4u;
			ecx += ebp;
			ebx += 4u;
		} while ((int32_t)edi < (int32_t)esi);
	}
	if ((int32_t)esi <= (int32_t)ebx)
		return;
	esi -= ebx;
	do
	{
		if (FLOAT_AT(ecx) < FLOAT_AT(edx))
			MEM32(edx) = MEM32(ecx);
		if (FLOAT_AT(ecx + 4u) < FLOAT_AT(edx + 4u))
			MEM32(edx + 4u) = MEM32(ecx + 4u);
		if (FLOAT_AT(ecx + 8u) < FLOAT_AT(edx + 8u))
			MEM32(edx + 8u) = MEM32(ecx + 8u);
		if (FLOAT_AT(ecx) > FLOAT_AT(edx + 0xCu))
			MEM32(edx + 0xCu) = MEM32(ecx);
		if (FLOAT_AT(ecx + 4u) > FLOAT_AT(edx + 0x10u))
			MEM32(edx + 0x10u) = MEM32(ecx + 4u);
		if (FLOAT_AT(ecx + 8u) > FLOAT_AT(edx + 0x14u))
			MEM32(edx + 0x14u) = MEM32(ecx + 8u);
		ecx += ebp;
		t1 = esi;
		esi = t1 - 1u;
	} while (t1 != 1u);
}

/* Writes into arg2/arg3 the two opposite corners of the box at arg0 chosen per axis by the sign of the
   direction vector at arg1, putting the box minimum first where the direction component is non-negative. */
