/* For each axis writes to arg3 the box-at-arg0 minimum expanded by the float arg2, clamped so it is no
   less than the value at arg1 and no greater than the box maximum shrunk by arg2. */
void BoxClampPointToInsetBox(uint32_t arg0, uint32_t arg1, uint32_t arg2, uint32_t arg3)
{
	uint32_t ecx = 0, edx = 0, esi = 0;
	uint32_t stack = 0;
	double f0 = 0;

	stack = arg0;
	edx = stack;
	f0 = x87_round(x87_float(arg2) + FLOAT_AT(edx));
	ecx = arg1;
	stack = float_to_bits((float)x87_round(FLOAT_AT(edx + 0xCu) - x87_float(arg2)));
	if (!(f0 > FLOAT_AT(ecx)))
	{
		if (!(FLOAT_AT(ecx) > x87_float(stack)))
			f0 = FLOAT_AT(ecx);
		else
			f0 = x87_float(stack);
	}
	esi = arg3;
	MEMF(esi) = (float)f0;
	f0 = x87_round(x87_float(arg2) + FLOAT_AT(edx + 4u));
	stack = float_to_bits((float)x87_round(FLOAT_AT(edx + 0x10u) - x87_float(arg2)));
	if (!(f0 > FLOAT_AT(ecx + 4u)))
	{
		if (!(FLOAT_AT(ecx + 4u) > x87_float(stack)))
			f0 = FLOAT_AT(ecx + 4u);
		else
			f0 = x87_float(stack);
	}
	MEMF(esi + 4u) = (float)f0;
	f0 = x87_round(x87_float(arg2) + FLOAT_AT(edx + 8u));
	stack = float_to_bits((float)x87_round(FLOAT_AT(edx + 0x14u) - x87_float(arg2)));
	if (f0 > FLOAT_AT(ecx + 8u))
	{
		MEMF(esi + 8u) = (float)f0;
		return;
	}
	if (!(FLOAT_AT(ecx + 8u) > x87_float(stack)))
	{
		MEM32(esi + 8u) = MEM32(ecx + 8u);
		return;
	}
	MEM32(esi + 8u) = stack;
}

/* Transforms the box at arg1 by passing its minimum and maximum points (arg1 and arg1+0xC) through
   FileReadTriples, returning the last transformed result. */
uint32_t BoxTransform(uint32_t arg0, uint32_t arg1)
{
	uint32_t arg0_2 = 0, arg1_2 = 0, arg2 = 0, edi = 0, edx = 0, esi = 0, ignored = 0, ignored_2 = 0;

	esi = arg1;
	edi = arg0;
	arg2 = 1u;
	arg1_2 = esi;
	arg0_2 = edi;
	FileReadTriples(arg0_2, arg1_2, arg2, &ignored, &ignored_2);
	arg2 = 1u;
	arg1_2 = esi + 0xCu;
	arg0_2 = edi;
	FileReadTriples(arg0_2, arg1_2, arg2, &ignored, &edx);
	return edx;
}

