		arg0_2 = edi;
		x86_call(vcFileReadU32_entry, 0x0012A3EFu, 2, arg0_2, arg1_2);
		ignored_2 = g_edx;
		arg2_2 = 1u;
		arg1_2 = esi - 0xCu;
		arg0_2 = edi;
		FileReadTriples(arg0_2, arg1_2, arg2_2, &ignored, &ignored_2);
		arg1_2 = esi;
		arg0_2 = edi;
		x86_call(vcFileReadU32_entry, 0x0012A402u, 2, arg0_2, arg1_2);
		ignored_2 = g_edx;
		arg2_2 = 1u;
