	MEM32(g_esp + 0xCu) = g_esp + 0x10u;
	ebx_2 = MEM32(g_esp + 0xCu);
	ecx = MEM32(g_esp + 8u);
	t2 = x87_round(FLOAT_AT(ebx_2 + 8u) * FLOAT_AT(ecx + 8u));
	MEMF(g_esp + 4u) = (float)x87_round(t2 + x87_round(x87_round(FLOAT_AT(ebx_2 + 4u) * FLOAT_AT(ecx + 4u)) + x87_round(FLOAT_AT(ebx_2) * FLOAT_AT(ecx))));
	edx = MEM32(g_esp + 0x24u);
	ecx = MEM32(g_esp + 0x20u);
	f0 = x87_round(FLOAT_AT(edx + 0xCu) + FLOAT_AT(ecx + 0xCu));
	ebx_2 = MEM32(g_esp);
