			t1 = x87_round(x87_round(x87_round(FLOAT_AT(ebx_2 + 0x18u) * FLOAT_AT(ecx)) + x87_round(x87_round(FLOAT_AT(ebx_2 + 0x1Cu) * FLOAT_AT(ecx + 4u)) + x87_round(FLOAT_AT(ebx_2 + 0x20u) * FLOAT_AT(ecx + 8u)))) + FLOAT_AT(edx + 8u));
			MEMF(eax) = (float)x87_round(x87_round(x87_round(FLOAT_AT(ebx_2) * FLOAT_AT(ecx)) + x87_round(x87_round(FLOAT_AT(ebx_2 + 4u) * FLOAT_AT(ecx + 4u)) + x87_round(FLOAT_AT(ebx_2 + 8u) * FLOAT_AT(ecx + 8u)))) + FLOAT_AT(edx));
